actions.script:
const yes = value => value === true || value === 'true' || value === 'Y'
const text = value => value === null || value === undefined ? '' : String(value).trim()
const asked = {name: text(name), enabled: yes(enabled), port: text(port), host: text(host), access: text(access),
    reason: text(reason), persist: yes(persist), endNow: yes(endNow), confirmLockout: yes(confirmLockout),
    confirmPublicHttp: yes(confirmPublicHttp), confirmDependents: yes(confirmDependents)}
// a field left at the value the form showed (its *Was) is not asked: sent at the value it has, it would still be
// written where it is held or kept elsewhere, pinning it in runtime/.env
for (const [key, was] of [['port', portWas], ['host', hostWas], ['access', accessWas]])
    if (was != null && asked[key] === text(was)) asked[key] = ''
const parameters = Object.fromEntries(Object.entries(asked).filter(([key, value]) => value !== ''))
const answer = ec.service.sync().name('org.moqui.admin.ListenerServices.set#Listener').parameters(parameters).call() || {}
listenerDialog = ''
if (answer.confirm || answer.reasonCode === 'portBusy') {
    // a guard's refusal or a busy port: the form again, with the confirmation the answer named (or the port)
    const refusal = ec.message.getErrorsString()
    ec.message.clearErrors()
    if (ec.web) ec.web.sessionAttributes.listenerConfirm = JSON.stringify(Object.assign({}, asked,
        {confirm: answer.confirm || '', reasonCode: answer.reasonCode || '', message: refusal}))
    ec.message.addMessage(ec.l10n.localize('Not changed yet:') + ' ' + refusal, 'warning')
    listenerDialog = 'ServicesPorts'
} else if (!ec.message.hasError()) {
    const failed = answer.applied === 'failed' || Array.from(answer.outcomeList || [])
        .some(outcome => outcome.name === answer.name && outcome.action === 'failed')
    ec.message.addMessage(String(answer.message || ''), failed ? 'warning' : 'success')
    for (const setting of Array.from(answer.settingList || []))
        ec.message.addMessage(setting.selector + ' ' + (setting.value ?? '') + ': ' + setting.note, 'info')
    for (const note of Array.from(answer.noteList || [])) ec.message.addMessage(String(note), 'info')
}

const L = text => ec.l10n.localize(text)
const DASH = '—'
servicesAllowed = ec.user.hasPermission('LISTENER_CONTROL')
let found = null
try {
    found = ec.service.sync().name('org.moqui.admin.ListenerServices.get#Listeners').call() || null
} catch (error) {
    ec.logger.error('Services and ports: the listeners could not be read: ' + String(error))
}
const refused = ec.message.hasError()
if (refused) ec.message.clearErrors()
servicesAvailable = !refused && !!found && found.listenerList != null
servicesRunning = !!(found && found.running)
const listed = servicesAvailable ? Array.from(found.listenerList) : []
const time = value => {
    const at = value ? Date.parse(String(value)) : NaN
    return Number.isFinite(at) ? ec.l10n.format(new Date(at), 'yyyy-MM-dd HH:mm:ss') : ''
}
const sourceOf = setting => String(setting.source || '') +
    (setting.fileLabel ? ': ' + setting.fileLabel + (setting.line ? ' ' + L('line') + ' ' + setting.line : '') : '')
const shown = value => value === null || value === undefined || value === '' ? L('empty') : String(value)
const STATES = {on: {text: L('On'), color: 'positive'}, off: {text: L('Off'), color: 'grey-6'},
    failed: {text: L('Failed'), color: 'negative'}, skipped: {text: L('Skipped'), color: 'warning'}}
servicesAccessOptions = [{value: 'open', label: L('Open: anyone reaches the sign-in dialog')},
    {value: 'login', label: L('Login: an account\'s password or key')}, {value: 'key', label: L('Key: a registered key only')}]

// ---- the listeners, each with what a holder of LISTENER_CONTROL may do to it ----
servicesRows = listed.map(row => {
    const name = String(row.name)
    const enabled = row.enabled === true
    const state = row.state === 'not-running'
        ? {text: enabled ? L('On in the conf') : L('Off in the conf'), color: 'grey-6'}
        : STATES[row.state] || {text: String(row.state || DASH), color: 'grey-6'}
    const port = row.port == null ? '' : String(row.port)
    const host = row.host == null ? '' : String(row.host)
    const own = Array.from(row.ownSettingList || [])
    const access = own.find(setting => setting.name === 'access') || null
    const switchable = row.switchable === true
    // a listener with a port setting and no port written cannot be turned on without one
    const needsMore = !!row.portSelector && !port
    const movable = !!row.portSelector || !!row.hostSelector || own.length > 0
    const problems = [row.lastError ? L('Last error') + ': ' + row.lastError : '',
        row.pending ? L('Waits for a restart') + ': ' + row.pending : '']
    return {
        name, key: name.replace(/\W/g, '_'), enabled, switchable,
        ownText: row.ownRequest ? L('You are connected through it') : '',
        stateText: state.text, stateColor: state.color,
        addressText: row.address || (port ? (host ? host + ' ' : '') + L('port') + ' ' + port : DASH),
        sinceText: [row.since ? L('since') + ' ' + time(row.since) : '', row.cause || ''].filter(part => part).join(' · '),
        connectionsText: row.connections != null ? String(row.connections) : DASH,
        detail: String(row.detail || ''),
        problemText: problems.filter(part => part).join(' · '),
        dependentsText: Array.from(row.dependents || []).join('; '),
        port, host, hasPort: !!row.portSelector, hasHost: !!row.hostSelector,
        hostTooltip: String(row.hostSelector || '').endsWith('@http-bind') ? L('An IP address, 0.0.0.0 for every address: HTTP and HTTPS both bind it')
            : L('An IP address, 0.0.0.0 for every address'),
        hasAccess: !!access, accessValue: access ? String(access.value || '') : '',
        canTurnOff: servicesAllowed && switchable && enabled,
        canTurnOn: servicesAllowed && switchable && !enabled && !needsMore,
        canChange: servicesAllowed && switchable && (enabled ? movable : needsMore),
        turnOffTitle: L('Turn off') + ' ' + name,
        changeButton: enabled ? L('Change…') : L('Turn on…'),
        changeTitle: (enabled ? L('Change') : L('Turn on')) + ' ' + name,
        changeSubmit: enabled ? L('Change') : L('Turn on')
    }
})

// ---- the settings behind them, and the services carried on one ----
const subSelectors = new Set(listed.flatMap(row => Array.from(row.subServiceList || []).map(service => String(service.selector))))
servicesSettingRows = listed.flatMap(row => Array.from(row.settingList || [])
    .filter(setting => !subSelectors.has(String(setting.selector)))
    .map(setting => ({listener: String(row.name), selector: String(setting.selector), valueText: shown(setting.value),
        sourceText: sourceOf(setting), envName: String(setting.envName || '')})))
servicesSubRows = listed.flatMap(row => Array.from(row.subServiceList || []).map(service => ({
    listener: String(row.name), title: L(String(service.title)), stateText: service.on ? L('On') : L('Off'),
    stateColor: service.on ? 'positive' : 'grey-6', selector: String(service.selector), sourceText: sourceOf(service)})))

// ---- the changes people made since the server started ----
servicesChangeRows = Array.from((found && found.recentChanges) || []).map(change => ({
    timeText: time(change.time), name: String(change.name), whoText: String(change.who || ''),
    changeText: String(change.from || '') + ' → ' + String(change.to || ''), reasonText: change.reason ? String(change.reason) : DASH,
    outcomeText: [String(change.outcome || ''), change.endNow ? L('connections ended at once') : '',
        change.persist ? '' : L('not kept past a restart')].filter(part => part).join(' · ')}))

// ---- a change refused by a guard or a busy port: its form again, once, with what it needs ----
servicesConfirm = null
if (servicesAllowed && ec.web) {
    let pending = null
    try { pending = JSON.parse(ec.web.sessionAttributes.remove('listenerConfirm') || 'null') } catch (error) { pending = null }
    const row = pending ? servicesRows.find(candidate => candidate.name === pending.name) : null
    if (row) {
        const CONFIRMS = {confirmLockout: L('Make the change though it leaves no way in over the network'),
            confirmPublicHttp: L('Turn plain HTTP on at a public address anyway'),
            confirmDependents: L('Turn SSH off though something depends on it')}
        const flag = value => value ? 'Y' : ''
        const portBusy = pending.reasonCode === 'portBusy'
        // exactly what was asked, with the confirmation the answer named; a busy port shows the port and address to
        // change, at the request's or the running ones, a field left at a running value (its *Was) not sent again
        servicesConfirm = {name: row.name, enabled: pending.enabled ? 'true' : 'false',
            port: pending.port || (portBusy ? row.port : ''), portWas: pending.port ? '' : row.port,
            host: pending.host || (portBusy ? row.host : ''), hostWas: pending.host ? '' : row.host,
            access: pending.access || '', accessWas: '', reason: pending.reason || '',
            showPort: row.hasPort && (portBusy || !!pending.port), showHost: row.hasHost && (portBusy || !!pending.host),
            showAccess: row.hasAccess && !!pending.access,
            persist: flag(pending.persist), endNow: flag(pending.endNow),
            confirmLockout: flag(pending.confirmLockout), confirmPublicHttp: flag(pending.confirmPublicHttp),
            confirmDependents: flag(pending.confirmDependents), confirm: CONFIRMS[pending.confirm] ? pending.confirm : '',
            confirmText: CONFIRMS[pending.confirm] || '', message: String(pending.message || ''),
            portBusy, turningOff: !pending.enabled,
            summary: (pending.enabled ? L('Turn on or change') : L('Turn off')) + ': ' + row.name}
    }
}
